	const implTask = taskExpression(IMPL_TASK_PREFIX, task, IMPL_TASK_MIDDLE) + " + JSON.stringify({ plan: planOut, scout: scoutOut }) + " + JSON.stringify(IMPL_TASK_SUFFIX);",
