/**
 * Factory workflow script builders.
 *
 * These functions generate the two fixed workflowScript bodies the factory
 * launches through pi-subagents:
 *
 *   1. build  — scout → plan → implement (one writer)
 *   2. review — three parallel fresh reviewers → optional single fix pass
 *
 * Rules encoded here:
 * - The human task and every machine-consumed value are embedded with
 *   JSON.stringify at generation time, so quotes, Markdown fences, shell-like
 *   text, and multiline prompts can never break out of the script.
 * - Every child uses a stable workflow key and fresh context.
 * - Every machine-consumed child result uses an outputSchema, and the scripts
 *   branch ONLY on structuredOutput — never on child prose.
 * - Malformed or missing structured output fails the stage closed
 *   (needs_attention / blocked), it never reaches the next stage unchecked.
 * - The review→fix loop is capped at exactly one fix pass by construction.
 * - The scripts never call runs.host: deterministic validation commands are
 *   executed by the factory extension itself from human-authored config.
 */

/** Stable workflow keys — also the keys the extension correlates in completion results. */
export const WORKFLOW_KEYS = {
	scout: "scout",
	plan: "plan",
	implement: "implement",
	reviewCorrectness: "review-correctness",
	reviewTests: "review-tests",
	reviewSimplicity: "review-simplicity",
	fix: "fix",
} as const;

export const REVIEW_KEYS = [
	WORKFLOW_KEYS.reviewCorrectness,
	WORKFLOW_KEYS.reviewTests,
	WORKFLOW_KEYS.reviewSimplicity,
] as const;

/** JSON Schema for scout structured output. The scout must not edit files. */
const SCOUT_SCHEMA = {
	type: "object",
	properties: {
		summary: { type: "string" },
		relevantFiles: { type: "array", items: { type: "string" } },
		constraints: { type: "array", items: { type: "string" } },
		risks: { type: "array", items: { type: "string" } },
		implementationSeam: { type: "string" },
		validationCommandsFound: { type: "array", items: { type: "string" } },
	},
	required: ["summary", "relevantFiles", "constraints", "risks", "implementationSeam", "validationCommandsFound"],
	additionalProperties: false,
} as const;

/** JSON Schema for planner structured output. */
const PLAN_SCHEMA = {
	type: "object",
	properties: {
		steps: { type: "array", items: { type: "string" } },
		filesToChange: { type: "array", items: { type: "string" } },
		nonGoals: { type: "array", items: { type: "string" } },
		validationPlan: { type: "array", items: { type: "string" } },
		decisionsRequiringApproval: { type: "array", items: { type: "string" } },
	},
	required: ["steps", "filesToChange", "nonGoals", "validationPlan", "decisionsRequiringApproval"],
	additionalProperties: false,
} as const;

/** JSON Schema for the implement/fix worker's checked acceptance handoff. */
const IMPL_SCHEMA = {
	type: "object",
	properties: {
		changedFiles: { type: "array", items: { type: "string" } },
		implementationSummary: { type: "string" },
		commandsRun: {
			type: "array",
			items: {
				type: "object",
				properties: { command: { type: "string" }, exitCode: { type: "integer" } },
				required: ["command", "exitCode"],
				additionalProperties: false,
			},
		},
		testsAddedOrUpdated: { type: "array", items: { type: "string" } },
		residualRisks: { type: "array", items: { type: "string" } },
		workLeftUndone: { type: "array", items: { type: "string" } },
		decisionsRequiringApproval: { type: "array", items: { type: "string" } },
	},
	required: [
		"changedFiles",
		"implementationSummary",
		"commandsRun",
		"testsAddedOrUpdated",
		"residualRisks",
		"workLeftUndone",
		"decisionsRequiringApproval",
	],
	additionalProperties: false,
} as const;

/** JSON Schema for reviewer structured output. Branching uses verdict only. */
const REVIEW_SCHEMA = {
	type: "object",
	properties: {
		verdict: { type: "string", enum: ["ok", "fix", "blocked"] },
		findings: {
			type: "array",
			items: {
				type: "object",
				properties: {
					priority: { type: "string", enum: ["P0", "P1", "P2", "P3"] },
					summary: { type: "string" },
					evidence: { type: "string" },
					file: { type: "string" },
					line: { type: "integer" },
				},
				required: ["priority", "summary", "evidence", "file", "line"],
				additionalProperties: false,
			},
		},
		remainingRisks: { type: "array", items: { type: "string" } },
	},
	required: ["verdict", "findings", "remainingRisks"],
	additionalProperties: false,
} as const;

/** Maximum embedded human task length (characters). Keeps generated scripts bounded. */
const MAX_TASK_LENGTH = 16_000;

/**
 * Safely encode the human task for embedding in a generated workflow script.
 * Throws on empty or oversized tasks so callers can fail closed before launch.
 */
export function encodeTask(task: string): string {
	const trimmed = task.trim();
	if (!trimmed) throw new Error("factory task must be a non-empty string.");
	if (trimmed.length > MAX_TASK_LENGTH) {
		throw new Error(`factory task must be at most ${MAX_TASK_LENGTH} characters (got ${trimmed.length}).`);
	}
	return JSON.stringify(trimmed);
}

/**
 * Checked acceptance policy applied to the implement and fix workers.
 * Enforced by pi-subagents itself, not by this extension.
 */
const WORKER_ACCEPTANCE = { level: "checked", evidence: ["commands-run", "changed-files"] } as const;

const SCOUT_TASK_PREFIX = [
	"You are the scout phase of a software factory. Recon only.",
	"",
	"## Task",
	"",
].join("\n");

const SCOUT_TASK_SUFFIX = [
	"",
	"## Rules",
	"",
	"- You MUST NOT edit, write, create, or delete any repository files. Read-only recon.",
	"- Return structured output with: a short summary; the relevant files (paths);",
	"  constraints that bind the implementation; likely risks; the recommended",
	"  implementation seam (where the change should land); and any existing",
	"  validation commands you find in trusted repository configuration",
	"  (package scripts, Makefile, mise tasks, CI config). Report commands only —",
	"  never run them, and never propose new ones.",
].join("\n");

const PLAN_TASK_PREFIX = [
	"You are the plan phase of a software factory. Read-only planning.",
	"",
	"## Task",
	"",
].join("\n");

const PLAN_TASK_MIDDLE = [
	"",
	"## Scout findings (validated structured output)",
	"",
].join("\n");

const PLAN_TASK_SUFFIX = [
	"",
	"## Rules",
	"",
	"- You MUST NOT edit, write, create, or delete any files. Produce a plan only.",
	"- Return structured output with: concrete implementation steps; files expected",
	"  to change; explicit non-goals; a validation plan; and any decisions that",
	"  require human approval (product, architecture, security, or scope calls).",
	"- If a required decision is human-owned, list it in decisionsRequiringApproval",
	"  instead of assuming. The factory stops on any unresolved decision.",
].join("\n");

const IMPL_TASK_PREFIX = [
	"You are the implement phase of a software factory. You are the single writer.",
	"",
	"## Human task",
	"",
].join("\n");

const IMPL_TASK_MIDDLE = [
	"",
	"## Validated plan and scout fields",
	"",
].join("\n");

const IMPL_TASK_SUFFIX = [
	"",
	"## Rules",
	"",
	"- Implement exactly the plan. Stay inside the listed files and non-goals.",
	"- Run the plan's validation commands and report each command with its exit",
	"  code in commandsRun. Do not commit, push, merge, publish, deploy, or release.",
	"- If a human-owned decision surfaces that the plan did not cover, stop and",
	"  list it in decisionsRequiringApproval instead of deciding yourself.",
	"- Report a checked acceptance handoff as structured output: changedFiles,",
	"  implementationSummary, commandsRun (with exit codes), testsAddedOrUpdated,",
	"  residualRisks, workLeftUndone, decisionsRequiringApproval.",
].join("\n");

const REVIEW_TASK_PREFIX = [
	"You are a fresh-context reviewer in a software factory. Read-only review.",
	"",
	"## Human task being implemented",
	"",
].join("\n");

const REVIEW_TASK_MIDDLE = [
	"",
	"## Implementation handoff and deterministic check results",
	"",
].join("\n");

const REVIEW_TASK_SUFFIX = [
	"",
	"## Rules",
	"",
	"- You MUST NOT edit, write, create, or delete any files.",
	"- Judge only the current working-tree changes against the handoff. Cite exact",
	"  files and lines as evidence. Do not invent issues.",
	"- Return structured output: verdict must be exactly one of ok, fix, blocked;",
	"  findings each with priority (P0-P3), summary, evidence, file, line (use 0",
	"  when not applicable); plus remainingRisks.",
	"- verdict meanings: ok = nothing worth fixing; fix = concrete in-scope fixes",
	"  a worker can apply now (list them as findings); blocked = requires a",
	"  product, architecture, security, or scope decision (explain in findings).",
].join("\n");

const FIX_TASK_PREFIX = [
	"You are the fix phase of a software factory. You are the single writer.",
	"",
	"## Human task",
	"",
].join("\n");

const FIX_TASK_MIDDLE = [
	"",
	"## In-scope reviewer findings to apply",
	"",
].join("\n");

const FIX_TASK_SUFFIX = [
	"",
	"## Rules",
	"",
	"- Apply ONLY the listed findings. Do not expand scope, refactor beyond the",
	"  findings, or act on blocked findings that need a human decision.",
	"- Do not commit, push, merge, publish, deploy, or release.",
	"- Report the same checked acceptance handoff as structured output as the",
	"  implement phase (changedFiles, implementationSummary, commandsRun with exit",
	"  codes, testsAddedOrUpdated, residualRisks, workLeftUndone,",
	"  decisionsRequiringApproval).",
].join("\n");

/**
 * Build a task expression for the generated script that safely embeds the
 * JSON-encoded human task between fixed sections. Everything is a JSON string
 * literal or a runtime concatenation, so quotes, Markdown fences, shell-like
 * text, and multiline prompts cannot break the generated script.
 */
function taskExpression(prefix: string, encodedTask: string, suffix: string): string {
	return `${JSON.stringify(prefix)} + ${encodedTask} + ${JSON.stringify(suffix)}`;
}

/**
 * Build the build-phase workflowScript: scout → plan → implement.
 * All dynamic values are JSON-encoded at generation time.
 */
export function buildBuildWorkflowScript(input: { task: string }): string {
	const task = encodeTask(input.task);
	const scoutTask = taskExpression(SCOUT_TASK_PREFIX, task, SCOUT_TASK_SUFFIX);
	const planTask = taskExpression(PLAN_TASK_PREFIX, task, PLAN_TASK_MIDDLE)
		+ " + JSON.stringify(scoutOut) + " + JSON.stringify(PLAN_TASK_SUFFIX);
	const implTask = taskExpression(IMPL_TASK_PREFIX, task, IMPL_TASK_MIDDLE)
		+ " + JSON.stringify({ plan: planOut, scout: scoutOut }) + " + JSON.stringify(IMPL_TASK_SUFFIX);
	const script = `
await state.set("factory.phase", "build:scout");
const scout = await runs.run(${JSON.stringify(WORKFLOW_KEYS.scout)}, {
  agent: "scout",
  context: "fresh",
  task: ${scoutTask},
  outputSchema: ${JSON.stringify(SCOUT_SCHEMA)}
});
const scoutOut = scout.structuredOutput;
if (!scoutOut || typeof scoutOut.summary !== "string" || !scoutOut.summary.trim() || !Array.isArray(scoutOut.relevantFiles)) {
  return { verdict: "needs_attention", stage: "scout", reason: "scout did not return valid structured output", runId: scout.runId };
}

await state.set("factory.phase", "build:plan");
const plan = await runs.run(${JSON.stringify(WORKFLOW_KEYS.plan)}, {
  agent: "planner",
  context: "fresh",
  task: ${planTask},
  outputSchema: ${JSON.stringify(PLAN_SCHEMA)}
});
const planOut = plan.structuredOutput;
if (!planOut || !Array.isArray(planOut.steps) || planOut.steps.length === 0 || !Array.isArray(planOut.filesToChange)) {
  return { verdict: "needs_attention", stage: "plan", reason: "planner did not return valid structured output", runId: plan.runId };
}
const planDecisions = Array.isArray(planOut.decisionsRequiringApproval) ? planOut.decisionsRequiringApproval : [];
if (planDecisions.length > 0) {
  return { verdict: "needs_approval", stage: "plan", decisions: planDecisions, plan: planOut, runId: plan.runId };
}

await state.set("factory.phase", "build:implement");
const impl = await runs.run(${JSON.stringify(WORKFLOW_KEYS.implement)}, {
  agent: "worker",
  context: "fresh",
  task: ${implTask},
  outputSchema: ${JSON.stringify(IMPL_SCHEMA)},
  acceptance: ${JSON.stringify(WORKER_ACCEPTANCE)}
});
const implOut = impl.structuredOutput;
if (!implOut || !Array.isArray(implOut.changedFiles) || typeof implOut.implementationSummary !== "string") {
  return { verdict: "needs_attention", stage: "implement", reason: "implement worker did not return a valid acceptance handoff", runId: impl.runId };
}
const implDecisions = Array.isArray(implOut.decisionsRequiringApproval) ? implOut.decisionsRequiringApproval : [];
if (implDecisions.length > 0) {
  return { verdict: "needs_approval", stage: "implement", decisions: implDecisions, handoff: implOut, runId: impl.runId };
}
return {
  verdict: "implemented",
  changedFiles: implOut.changedFiles,
  summary: implOut.implementationSummary,
  commandsRun: Array.isArray(implOut.commandsRun) ? implOut.commandsRun : [],
  tests: Array.isArray(implOut.testsAddedOrUpdated) ? implOut.testsAddedOrUpdated : [],
  residualRisks: Array.isArray(implOut.residualRisks) ? implOut.residualRisks : [],
  workLeftUndone: Array.isArray(implOut.workLeftUndone) ? implOut.workLeftUndone : [],
  runId: impl.runId
};
`.trim();
	return script;
}

/**
 * Build the review-phase workflowScript: three parallel fresh reviewers,
 * branching ONLY on structured verdicts, with at most one fix pass.
 */
export function buildReviewWorkflowScript(input: {
	task: string;
	handoff: Record<string, unknown>;
	checks: Array<{ name: string; exitCode: number | null }>;
}): string {
	const task = encodeTask(input.task);
	const reviewContext = JSON.stringify({ handoff: input.handoff, deterministicChecks: input.checks });
	const reviewTask = taskExpression(REVIEW_TASK_PREFIX, task, REVIEW_TASK_MIDDLE)
		+ " + " + JSON.stringify(reviewContext) + " + " + JSON.stringify(REVIEW_TASK_SUFFIX);
	const fixTask = taskExpression(FIX_TASK_PREFIX, task, FIX_TASK_MIDDLE)
		+ " + JSON.stringify({ findings: needsFix.flatMap(v => v.findings), remainingRisks: needsFix.flatMap(v => v.remainingRisks) }) + "
		+ JSON.stringify(FIX_TASK_SUFFIX);
	const script = `
await state.set("factory.phase", "review");
function reviewVerdict(result) {
  if (!result || !result.structuredOutput) return "blocked";
  const verdict = result.structuredOutput.verdict;
  if (verdict === "ok" || verdict === "fix" || verdict === "blocked") return verdict;
  return "blocked";
}
const reviews = await runs.all([
  { key: ${JSON.stringify(WORKFLOW_KEYS.reviewCorrectness)}, agent: "reviewer", context: "fresh", task: ${reviewTask}, outputSchema: ${JSON.stringify(REVIEW_SCHEMA)} },
  { key: ${JSON.stringify(WORKFLOW_KEYS.reviewTests)}, agent: "reviewer", context: "fresh", task: ${reviewTask}, outputSchema: ${JSON.stringify(REVIEW_SCHEMA)} },
  { key: ${JSON.stringify(WORKFLOW_KEYS.reviewSimplicity)}, agent: "reviewer", context: "fresh", task: ${reviewTask}, outputSchema: ${JSON.stringify(REVIEW_SCHEMA)} }
]);
const reviewKeys = ${JSON.stringify(REVIEW_KEYS)};
const verdicts = reviews.map(function (result, index) {
  const so = result && result.structuredOutput;
  return {
    key: reviewKeys[index],
    verdict: reviewVerdict(result),
    findings: so && Array.isArray(so.findings) ? so.findings : [],
    remainingRisks: so && Array.isArray(so.remainingRisks) ? so.remainingRisks : [],
    runId: result ? result.runId : undefined
  };
});
const needsFix = verdicts.filter(function (v) { return v.verdict === "fix"; });
const blockedReviews = verdicts.filter(function (v) { return v.verdict === "blocked"; });
if (needsFix.length === 0) {
  if (blockedReviews.length > 0) {
    return { verdict: "blocked", reviews: verdicts, decisions: blockedReviews.flatMap(function (v) { return v.findings; }) };
  }
  return { verdict: "ok", reviews: verdicts };
}

await state.set("factory.phase", "fix");
const fix = await runs.run(${JSON.stringify(WORKFLOW_KEYS.fix)}, {
  agent: "worker",
  context: "fresh",
  task: ${fixTask},
  outputSchema: ${JSON.stringify(IMPL_SCHEMA)},
  acceptance: ${JSON.stringify(WORKER_ACCEPTANCE)}
});
const fixOut = fix.structuredOutput;
if (!fixOut || !Array.isArray(fixOut.changedFiles) || typeof fixOut.implementationSummary !== "string") {
  return { verdict: "needs_attention", stage: "fix", reason: "fix worker did not return a valid acceptance handoff", reviews: verdicts, runId: fix.runId };
}
const fixDecisions = Array.isArray(fixOut.decisionsRequiringApproval) ? fixOut.decisionsRequiringApproval : [];
if (fixDecisions.length > 0) {
  return { verdict: "needs_approval", stage: "fix", decisions: fixDecisions, reviews: verdicts, handoff: fixOut, runId: fix.runId };
}
return {
  verdict: "fixed",
  reviews: verdicts,
  changedFiles: fixOut.changedFiles,
  summary: fixOut.implementationSummary,
  commandsRun: Array.isArray(fixOut.commandsRun) ? fixOut.commandsRun : [],
  tests: Array.isArray(fixOut.testsAddedOrUpdated) ? fixOut.testsAddedOrUpdated : [],
  residualRisks: Array.isArray(fixOut.residualRisks) ? fixOut.residualRisks : [],
  workLeftUndone: Array.isArray(fixOut.workLeftUndone) ? fixOut.workLeftUndone : [],
  runId: fix.runId
};
`.trim();
	return script;
}

/**
 * In-process RPC client for the pi-subagents event-bus RPC
 * (`subagents:rpc:v1:*`).
 *
 * The factory never imports pi-subagents internals: it sends requests on the
 * documented request event, correlates replies by request ID on the per-request
 * reply event, and fails closed on error replies and timeouts.
 */

export const RPC_READY_EVENT = "subagents:rpc:v1:ready";
export const RPC_REQUEST_EVENT = "subagents:rpc:v1:request";
export const RPC_REPLY_EVENT_PREFIX = "subagents:rpc:v1:reply:";

/** Minimal event-bus surface (pi.events satisfies this). */
export interface RpcEventBus {
	on(event: string, handler: (data: unknown) => void): unknown;
	emit(event: string, data: unknown): unknown;
}

export class FactoryRpcError extends Error {
	readonly code: string;

	constructor(code: string, message: string) {
		super(message);
		this.name = "FactoryRpcError";
		this.code = code;
	}
}

export interface RpcRequestOptions {
	/** How long to wait for a correlated reply before failing. */
	timeoutMs?: number;
	/** Override the generated request ID (used by tests). */
	requestId?: string;
}

export interface RpcReplyEnvelope {
	version: number;
	requestId: string;
	success: boolean;
	data?: unknown;
	error?: { code: string; message: string };
}

function defaultTimeout(method: string): number {
	return method === "spawn" ? 120_000 : 30_000;
}

/**
 * Send one RPC request and await the correlated reply.
 *
 * Replies are matched strictly by requestId; replies for other requests are
 * ignored. A timeout is a failure, never a success with unknown state.
 */
export function rpcRequest<T = unknown>(
	bus: RpcEventBus,
	method: string,
	params: Record<string, unknown> | undefined,
	options: RpcRequestOptions = {},
): Promise<T> {
	const requestId = options.requestId ?? crypto.randomUUID();
	const timeoutMs = options.timeoutMs ?? defaultTimeout(method);
	return new Promise<T>((resolve, reject) => {
		let settled = false;
		const unsubscribe = bus.on(`${RPC_REPLY_EVENT_PREFIX}${requestId}`, (raw) => {
			const reply = raw as RpcReplyEnvelope;
			if (!reply || typeof reply !== "object" || reply.requestId !== requestId) return;
			if (settled) return;
			settled = true;
			clearTimeout(timer);
			unsubscribe?.();
			if (reply.success) {
				resolve(reply.data as T);
			} else {
				const error = reply.error ?? { code: "execution_failed", message: "RPC reply reported failure without details." };
				reject(new FactoryRpcError(error.code, error.message));
			}
		});
		const timer = setTimeout(() => {
			if (settled) return;
			settled = true;
			unsubscribe?.();
			reject(new FactoryRpcError("timeout", `pi-subagents RPC '${method}' (${requestId}) timed out after ${timeoutMs}ms.`));
		}, timeoutMs);
		bus.emit(RPC_REQUEST_EVENT, {
			version: 1,
			requestId,
			method,
			...(params !== undefined ? { params } : {}),
			source: { extension: "sof-pi.factory" },
		});
	});
}

export interface SubagentsCapabilities {
	methods: string[];
	capabilities: Record<string, unknown>;
	events: Record<string, string>;
}

/**
 * Verify that the installed pi-subagents extension is alive and speaks the
 * expected RPC protocol. Pings with a short timeout, then retries once to
 * tolerate startup ordering (the bridge may register after we load).
 */
export async function rpcPing(bus: RpcEventBus): Promise<SubagentsCapabilities> {
	const attempts = [0, 1] as const;
	let lastError: unknown;
	for (const attempt of attempts) {
		if (attempt > 0) await new Promise((resolve) => setTimeout(resolve, 1_000));
		try {
			const data = await rpcRequest<SubagentsCapabilities>(bus, "ping", undefined, { timeoutMs: 5_000 });
			if (!Array.isArray(data?.methods) || !data.methods.includes("spawn")) {
				throw new FactoryRpcError("invalid_state", "pi-subagents RPC is reachable but does not advertise the spawn method.");
			}
			return data;
		} catch (error) {
			lastError = error;
		}
	}
	throw new FactoryRpcError(
		"unavailable",
		`pi-subagents is not responding on the in-process RPC bus. Is the pi-subagents package installed and loaded? Last error: ${
			lastError instanceof Error ? lastError.message : String(lastError)
		}`,
	);
}

/**
 * Deterministic validation checks.
 *
 * Commands come ONLY from the strictly-validated, human-authored factory
 * configuration. Model output is never executed here: child agents may report
 * commands they ran, but the factory's own checks are decided entirely by
 * configuration.
 */

import { exec } from "node:child_process";

import type { FactoryConfig } from "./config.ts";

export interface CheckResult {
	name: string;
	command: string;
	exitCode: number | null;
	timedOut: boolean;
	durationMs: number;
	/** Bounded tail of combined stdout+stderr. */
	outputTail: string;
}

const OUTPUT_TAIL_BYTES = 2_000;
const MAX_OUTPUT_BYTES = 8 * 1024 * 1024;

/** Pluggable command runner (injected in tests). */
export type CheckRunner = (
	command: string,
	cwd: string,
	timeoutMs: number,
) => Promise<{ exitCode: number | null; timedOut: boolean; output: string }>;

function tail(text: string): string {
	return text.length <= OUTPUT_TAIL_BYTES ? text : `…${text.slice(-OUTPUT_TAIL_BYTES)}`;
}

/** Default runner backed by the platform shell (commands are human-authored). */
export function createExecCheckRunner(): CheckRunner {
	return (command, cwd, timeoutMs) =>
		new Promise((resolve) => {
			const startedAt = Date.now();
			exec(
				command,
				{ cwd, timeout: timeoutMs, maxBuffer: MAX_OUTPUT_BYTES, encoding: "utf8" },
				(error, stdout, stderr) => {
					const timedOut = Boolean(error && (error as { killed?: boolean }).killed && (error as { signal?: string }).signal === "SIGTERM");
					const exitCode = error === null ? 0 : typeof (error as { code?: unknown }).code === "number" ? (error as { code: number }).code : null;
					const output = `${stdout ?? ""}${stderr ?? ""}`;
					resolve({ exitCode, timedOut, output: `${output}\n[duration ${Date.now() - startedAt}ms]` });
				},
			);
		});
}

/**
 * Run every configured validation command in order, collecting bounded
 * results. A command that fails to spawn is a failed check (exitCode null),
 * not a crash of the factory.
 */
export async function runValidationChecks(
	config: FactoryConfig,
	cwd: string,
	runner: CheckRunner = createExecCheckRunner(),
): Promise<CheckResult[]> {
	const results: CheckResult[] = [];
	for (const { name, command } of config.validationCommands) {
		const startedAt = Date.now();
		const outcome = await runner(command, cwd, config.commandTimeoutMs);
		results.push({
			name,
			command,
			exitCode: outcome.exitCode,
			timedOut: outcome.timedOut,
			durationMs: Date.now() - startedAt,
			outputTail: tail(outcome.output),
		});
	}
	return results;
}

export function allChecksPassed(checks: CheckResult[]): boolean {
	return checks.every((check) => !check.timedOut && check.exitCode === 0);
}

/**
 * Factory run state: a bounded, serializable record of the latest factory run
 * in this session. Persisted as a session entry (like the learning extension)
 * so /factory-status survives restarts and preserves run, child, and mission
 * references needed for recovery.
 */

export type FactoryPhase =
	| "build"
	| "checks"
	| "review"
	| "final-checks"
	| "complete"
	| "needs_approval"
	| "needs_attention"
	| "failed";

export const ACTIVE_PHASES: readonly FactoryPhase[] = ["build", "checks", "review", "final-checks"];

export interface FactoryCheckRecord {
	name: string;
	command: string;
	exitCode: number | null;
	timedOut: boolean;
	durationMs: number;
	outputTail: string;
}

export interface FactoryHandoffRecord {
	changedFiles: string[];
	summary: string;
	commandsRun: Array<{ command: string; exitCode: number }>;
	testsAddedOrUpdated: string[];
	residualRisks: string[];
	workLeftUndone: string[];
}

export interface FactoryRunState {
	task: string;
	phase: FactoryPhase;
	buildRunId?: string;
	buildMissionId?: string;
	reviewRunId?: string;
	reviewMissionId?: string;
	checks?: FactoryCheckRecord[];
	finalChecks?: FactoryCheckRecord[];
	handoff?: FactoryHandoffRecord;
	reviewVerdict?: string;
	decisions?: string[];
	/** Workflow-level verdict from the review workflow (ok/fixed/blocked/…). */
	outcome?: string;
	error?: string;
	startedAt: string;
	updatedAt: string;
}

export const FACTORY_STATE_ENTRY = "factory-state";

const MAX_LIST_ITEMS = 32;
const MAX_STRING_LENGTH = 2_000;

function boundedString(value: unknown, max = MAX_STRING_LENGTH): string {
	return typeof value === "string" ? value.slice(0, max) : "";
}

function boundedStringList(value: unknown): string[] {
	if (!Array.isArray(value)) return [];
	return value
		.filter((item): item is string => typeof item === "string")
		.slice(0, MAX_LIST_ITEMS)
		.map((item) => item.slice(0, 500));
}

function boundedCheckRecords(value: unknown): FactoryCheckRecord[] | undefined {
	if (!Array.isArray(value)) return undefined;
	const records = value.slice(0, MAX_LIST_ITEMS).map((raw): FactoryCheckRecord | null => {
		if (!raw || typeof raw !== "object") return null;
		const record = raw as Record<string, unknown>;
		return {
			name: boundedString(record.name, 100),
			command: boundedString(record.command, 500),
			exitCode: typeof record.exitCode === "number" ? record.exitCode : null,
			timedOut: record.timedOut === true,
			durationMs: typeof record.durationMs === "number" ? record.durationMs : 0,
			outputTail: boundedString(record.outputTail),
		};
	});
	return records.every((record) => record !== null) ? (records as FactoryCheckRecord[]) : undefined;
}

function boundedHandoff(value: unknown): FactoryHandoffRecord | undefined {
	if (!value || typeof value !== "object") return undefined;
	const record = value as Record<string, unknown>;
	const summary = boundedString(record.summary ?? record.implementationSummary);
	if (!summary) return undefined;
	const commandsRun = Array.isArray(record.commandsRun)
		? record.commandsRun
			.slice(0, MAX_LIST_ITEMS)
			.map((entry) => {
				if (!entry || typeof entry !== "object") return null;
				const command = (entry as Record<string, unknown>).command;
				const exitCode = (entry as Record<string, unknown>).exitCode;
				if (typeof command !== "string" || typeof exitCode !== "number") return null;
				return { command: command.slice(0, 500), exitCode };
			})
			.filter((entry): entry is { command: string; exitCode: number } => entry !== null)
		: [];
	return {
		changedFiles: boundedStringList(record.changedFiles),
		summary,
		commandsRun,
		testsAddedOrUpdated: boundedStringList(record.testsAddedOrUpdated ?? record.tests),
		residualRisks: boundedStringList(record.residualRisks),
		workLeftUndone: boundedStringList(record.workLeftUndone),
	};
}

/**
 * Validate a restored/serialized factory state. Returns undefined for
 * incompatible data instead of guessing (fail closed on restore).
 */
export function isFactoryRunState(value: unknown): FactoryRunState | undefined {
	if (!value || typeof value !== "object") return undefined;
	const record = value as Record<string, unknown>;
	if (record.task !== undefined && typeof record.task !== "string") return undefined;
	const phase = record.phase;
	if (typeof phase !== "string") return undefined;
	const allowed = new Set<string>([...ACTIVE_PHASES, "complete", "needs_approval", "needs_attention", "failed"]);
	if (!allowed.has(phase)) return undefined;
	const state: FactoryRunState = {
		task: boundedString(record.task, 4_000),
		phase: phase as FactoryPhase,
		startedAt: boundedString(record.startedAt, 40),
		updatedAt: boundedString(record.updatedAt, 40),
	};
	for (const field of ["buildRunId", "buildMissionId", "reviewRunId", "reviewMissionId", "outcome", "error"] as const) {
		const raw = record[field];
		if (typeof raw === "string" && raw) Object.assign(state, { [field]: boundedString(raw, 200) });
	}
	if (typeof record.reviewVerdict === "string" && record.reviewVerdict) state.reviewVerdict = boundedString(record.reviewVerdict, 40);
	if (Array.isArray(record.decisions)) state.decisions = boundedStringList(record.decisions);
	const checks = boundedCheckRecords(record.checks);
	if (checks) state.checks = checks;
	const finalChecks = boundedCheckRecords(record.finalChecks);
	if (finalChecks) state.finalChecks = finalChecks;
	const handoff = boundedHandoff(record.handoff);
	if (handoff) state.handoff = handoff;
	return state;
}

/** Extract a bounded, typed handoff record from a workflow child structured output. */
export function handoffFromStructuredOutput(value: unknown): FactoryHandoffRecord | undefined {
	if (!value || typeof value !== "object") return undefined;
	const record = value as Record<string, unknown>;
	if (!Array.isArray(record.changedFiles) || typeof record.implementationSummary !== "string") return undefined;
	return boundedHandoff(value);
}

/** Extract the implement/fix child's structured output from a completion payload. */
export function childStructuredOutput(
	results: unknown,
	workflowKey: string,
): { structuredOutput: unknown; status: string | undefined; runId: string | undefined } | undefined {
	if (!Array.isArray(results)) return undefined;
	for (const raw of results) {
		if (!raw || typeof raw !== "object") continue;
		const entry = raw as Record<string, unknown>;
		if (entry.workflowKey !== workflowKey) continue;
		return {
			structuredOutput: entry.structuredOutput,
			status: typeof entry.status === "string" ? entry.status : undefined,
			runId: typeof entry.runId === "string" ? entry.runId : undefined,
		};
	}
	return undefined;
}

/** Collect every child's workflow key + structured verdict from a completion payload. */
export function childResults(results: unknown): Array<{ workflowKey: string; status: string; structuredOutput: unknown }> {
	if (!Array.isArray(results)) return [];
	const out: Array<{ workflowKey: string; status: string; structuredOutput: unknown }> = [];
	for (const raw of results) {
		if (!raw || typeof raw !== "object") continue;
		const entry = raw as Record<string, unknown>;
		if (typeof entry.workflowKey !== "string") continue;
		out.push({
			workflowKey: entry.workflowKey,
			status: typeof entry.status === "string" ? entry.status : "unknown",
			structuredOutput: entry.structuredOutput,
		});
	}
	return out;
}

/**
 * `/factory <task>` — a minimal, reliable software factory.
 *
 * The parent Pi session stays the orchestrator; this extension is a thin,
 * human-owned launcher on top of the installed pi-subagents extension. It owns
 * only: trust/baseline validation, strict config parsing, workflow generation,
 * RPC correlation, and deterministic validation checks. Execution, lifecycle,
 * missions, artifacts, status, resume, and Herdr integration stay with
 * pi-subagents.
 *
 * Pipeline (two bounded async workflows, checks in between):
 *
 *   build workflow   scout → plan → implement (single writer)
 *   deterministic    human-authored validation commands from .pi/factory.json
 *   review workflow  3 parallel fresh reviewers → at most one fix pass
 *   deterministic    the same trusted commands, rerun as final verification
 *
 * Deliberate deviation: pi-subagents v0.61 grants runs.host only to named
 * workflow resources (npm test / npm run typecheck), so inline workflowScripts
 * launched through the public execution boundary cannot use it. The factory
 * therefore runs the trusted validation commands in this extension process,
 * between the two workflows. Commands come ONLY from .pi/factory.json — never
 * from model output — so the security property ("model-proposed commands are
 * never executed") is preserved.
 */

import { execFile } from "node:child_process";
import { randomUUID } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";

import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
import { CONFIG_DIR_NAME } from "@earendil-works/pi-coding-agent";

import { parseFactoryConfig, FACTORY_CONFIG_FILENAME, type FactoryConfig } from "./src/config.ts";
import { allChecksPassed, runValidationChecks } from "./src/checks.ts";
import { FACTORY_RPC_SOURCE_LABEL_UNUSED as _UNUSED } from "./src/labels.ts";
import {
	FactoryRpcError,
	rpcPing,
	rpcRequest,
} from "./src/rpc.ts";
import {
	ACTIVE_PHASES,
	FACTORY_STATE_ENTRY,
	childStructuredOutput,
	handoffFromStructuredOutput,
	isFactoryRunState,
	type FactoryCheckRecord,
	type FactoryHandoffRecord,
	type FactoryRunState,
} from "./src/state.ts";
import { buildBuildWorkflowScript, buildReviewWorkflowScript } from "./src/workflow.ts";

const ASYNC_COMPLETE_EVENT = "subagent:async-complete";

function nowIso(): string {
	return new Date().toISOString();
}

function formatChecks(checks: FactoryCheckRecord[]): string {
	return checks
		.map((check) => {
			const status = check.timedOut ? "TIMEOUT" : check.exitCode === 0 ? "ok" : `exit ${check.exitCode ?? "?"}`;
			return `  - ${check.name}: ${status} (${check.durationMs}ms)`;
		})
		.join("\n");
}

function formatState(state: FactoryRunState): string {
	const lines: string[] = [
		"Software factory",
		`  Task: ${state.task}`,
		`  Phase: ${state.phase}`,
	];
	if (state.buildRunId) lines.push(`  Build run: ${state.buildRunId}${state.buildMissionId ? ` (mission ${state.buildMissionId})` : ""}`);
	if (state.reviewRunId) lines.push(`  Review run: ${state.reviewRunId}${state.reviewMissionId ? ` (mission ${state.reviewMissionId})` : ""}`);
	if (state.handoff) {
		lines.push(`  Changed files: ${state.handoff.changedFiles.length ? state.handoff.changedFiles.join(", ") : "(none reported)"}`);
	}
	if (state.checks) lines.push("  Checks:\n" + formatChecks(state.checks));
	if (state.finalChecks) lines.push("  Final checks:\n" + formatChecks(state.finalChecks));
	if (state.reviewVerdict) lines.push(`  Reviewers: ${state.reviewVerdict}`);
	if (state.outcome) lines.push(`  Outcome: ${state.outcome}`);
	if (state.decisions?.length) lines.push(`  Decisions requiring human approval:\n${state.decisions.map((d) => `  - ${d}`).join("\n")}`);
	if (state.handoff?.residualRisks.length) lines.push(`  Residual risks: ${state.handoff.residualRisks.join("; ")}`);
	if (state.handoff?.workLeftUndone.length) lines.push(`  Work left undone: ${state.handoff.workLeftUndone.join("; ")}`);
	if (state.error) lines.push(`  Error: ${state.error}`);
	lines.push("  No commit, push, deploy, or release was performed.");
	return lines.join("\n");
}

export default function factoryExtension(pi: ExtensionAPI) {
	let state: FactoryRunState | undefined;

	const restore = (ctx: ExtensionContext) => {
		let restored: FactoryRunState | undefined;
		for (const entry of ctx.sessionManager.getBranch()) {
			if (entry.type !== "custom" || entry.customType !== FACTORY_STATE_ENTRY) continue;
			// Newest matching entry wins; incompatible entries are skipped (fail closed).
			const parsed = isFactoryRunState(entry.data);
			if (parsed) restored = parsed;
		}
		state = restored;
	};

	const save = () => {
		if (!state) return;
		pi.appendEntry(FACTORY_STATE_ENTRY, state);
	};

	const updateStatus = (ctx: ExtensionContext, label?: string) => {
		if (!state) return;
		const active = ACTIVE_PHASES.includes(state.phase);
		if (label) ctx.ui.setStatus("factory", label);
		else if (active) ctx.ui.setStatus("factory", `factory: ${state.phase}`);
		else ctx.ui.setStatus("factory", undefined);
	};

	// ---- RPC helpers ----------------------------------------------------

	const spawnWorkflow = async (
		script: string,
		input: { task: string; phase: string },
		config: FactoryConfig,
	): Promise<string> => {
		const title = `Factory ${input.phase}: ${input.task.slice(0, 80)}`.replace(/[\r\n]+/g, " ");
		const data = await rpcRequest<{ text?: string; details?: { runId?: string; asyncDir?: string } }>(pi.events, "spawn", {
			workflowScript: script,
			mission: { title },
			timeoutMs: config.timeoutMs,
			globalConcurrencyLimit: config.maxConcurrency,
		});
		const runId = data?.details?.runId;
		if (typeof runId !== "string" || !runId) {
			throw new Error(`pi-subagents accepted the workflow but returned no run id. Response: ${JSON.stringify(data ?? null).slice(0, 500)}`);
		}
		return runId;
	};

	const queryMissionId = async (runId: string): Promise<string | undefined> => {
		try {
			const data = await rpcRequest<{ text?: string }>(pi.events, "status", { id: runId }, { timeoutMs: 20_000 });
			const match = /Mission:\s+(\S+)/.exec(data?.text ?? "");
			return match?.[1];
		} catch {
			return undefined; // Mission id is display/recovery metadata only.
		}
	};

	// ---- Baseline validation -------------------------------------------

	const runGit = (args: string[], cwd: string): Promise<{ code: number; output: string }> =>
		new Promise((resolve) => {
			execFile("git", args, { cwd, encoding: "utf8", timeout: 15_000 }, (error, stdout, stderr) => {
				const code = error === null ? 0 : typeof (error as { code?: unknown }).code === "number" ? (error as { code: number }).code : 1;
				resolve({ code, output: `${stdout ?? ""}${stderr ?? ""}`.trim() });
			});
		});

	const loadConfig = (ctx: ExtensionContext): FactoryConfig | undefined => {
		const path = join(ctx.cwd, CONFIG_DIR_NAME, FACTORY_CONFIG_FILENAME);
		let raw: unknown;
		try {
			raw = JSON.parse(readFileSync(path, "utf8"));
		} catch (error) {
			ctx.ui.notify(
				`/factory needs human-authored configuration at ${path} (${error instanceof Error ? error.message : String(error)}). ` +
					`See extensions/factory/README.md for the schema.`,
				"error",
			);
			return undefined;
		}
		const parsed = parseFactoryConfig(raw);
		if (!parsed.ok) {
			ctx.ui.notify(`Invalid ${path}:\n${parsed.errors.map((e) => `  - ${e}`).join("\n")}`, "error");
			return undefined;
		}
		return parsed.config;
	};

	const validateBaseline = async (ctx: ExtensionContext, config: FactoryConfig): Promise<boolean> => {
		const inside = await runGit(["rev-parse", "--is-inside-work-tree"], ctx.cwd);
		if (inside.code !== 0 || inside.output !== "true") {
			ctx.ui.notify(`/factory must run inside a git work tree (current: ${ctx.cwd}).`, "error");
			return false;
		}
		const status = await runGit(["status", "--porcelain"], ctx.cwd);
		if (status.output && !config.allowDirtyBaseline) {
			const sample = status.output.split("\n").slice(0, 10).join("\n");
			ctx.ui.notify(
				`/factory refuses a dirty git baseline (set "allowDirtyBaseline": true in ${FACTORY_CONFIG_FILENAME} to override):\n${sample}`,
				"error",
			);
			return false;
		}
		return true;
	};

	// ---- Pipeline continuation ------------------------------------------

	const runChecksAndContinue = async (ctx: ExtensionContext, config: FactoryConfig) => {
		if (!state) return;
		state.phase = "checks";
		state.updatedAt = nowIso();
		save();
		updateStatus(ctx);
		let checks: FactoryCheckRecord[];
		try {
			checks = await runValidationChecks(config, ctx.cwd);
		} catch (error) {
			state.phase = "failed";
			state.error = `deterministic checks crashed: ${error instanceof Error ? error.message : String(error)}`;
			state.updatedAt = nowIso();
			save();
			updateStatus(ctx);
			ctx.ui.notify(`Factory failed: ${state.error}`, "error");
			return;
		}
		state.checks = checks;
		if (!allChecksPassed(checks)) {
			state.phase = "failed";
			state.error = "deterministic validation failed after implementation — no fix loop is attempted; fix and rerun /factory.";
			state.updatedAt = nowIso();
			save();
			updateStatus(ctx);
			ctx.ui.notify(`Factory failed validation:\n${formatChecks(checks)}`, "error");
			return;
		}
		const script = buildReviewWorkflowScript({
			task: state.task,
			handoff: state.handoff as unknown as Record<string, unknown>,
			checks: checks.map(({ name, exitCode }) => ({ name, exitCode })),
		});
		try {
			const runId = await spawnWorkflow(script, { task: state.task, phase: "review" }, config);
			state.reviewRunId = runId;
			state.phase = "review";
			state.updatedAt = nowIso();
			state.reviewMissionId = await queryMissionId(runId);
		} catch (error) {
			state.phase = "failed";
			state.error = `failed to launch review workflow: ${error instanceof Error ? error.message : String(error)}`;
		}
		state.updatedAt = nowIso();
		save();
		updateStatus(ctx);
		if (state.phase === "failed") ctx.ui.notify(`Factory failed: ${state.error}`, "error");
	};

	const runFinalChecksAndFinish = async (ctx: ExtensionContext, config: FactoryConfig) => {
		if (!state) return;
		state.phase = "final-checks";
		state.updatedAt = nowIso();
		save();
		updateStatus(ctx);
		try {
			const finalChecks = await runValidationChecks(config, ctx.cwd);
			state.finalChecks = finalChecks;
			if (!allChecksPassed(finalChecks)) {
				state.phase = "failed";
				state.error = "final verification failed after the fix pass — the factory is capped at one fix pass; inspect and rerun.";
			}
		} catch (error) {
			state.phase = "failed";
			state.error = `final checks crashed: ${error instanceof Error ? error.message : String(error)}`;
		}
		state.updatedAt = nowIso();
		save();
		updateStatus(ctx);
		if (state.phase === "complete") ctx.ui.notify(`Factory complete.\n${formatState(state)}`, "info");
		else ctx.ui.notify(`Factory failed: ${state.error}`, "error");
	};

	const markNeedsApproval = (decisions: string[], source: string) => {
		if (!state) return;
		state.phase = "needs_approval";
		state.decisions = decisions;
		state.error = `${source} requires human decisions before the factory can continue.`;
		state.updatedAt = nowIso();
		save();
	};

	const handleBuildCompletion = async (ctx: ExtensionContext, payload: Record<string, unknown>, config: FactoryConfig) => {
		if (!state) return;
		state.buildMissionId = state.buildMissionId ?? (state.buildRunId ? await queryMissionId(state.buildRunId) : undefined);
		if (payload.success === false || payload.stopped === true || payload.timedOut === true || payload.interrupted === true) {
			state.phase = "failed";
			state.error = `build workflow did not complete (state: ${String(payload.state ?? "unknown")}, summary: ${boundedSummary(payload.summary)}).`;
			state.updatedAt = nowIso();
			save();
			updateStatus(ctx);
			ctx.ui.notify(`Factory failed: ${state.error}`, "error");
			return;
		}
		const impl = childStructuredOutput(payload.results, "implement");
		const handoff = impl?.status === "completed" ? handoffFromStructuredOutput(impl.structuredOutput) : undefined;
		if (handoff) {
			state.handoff = handoff;
			await runChecksAndContinue(ctx, config);
			return;
		}
		const plan = childStructuredOutput(payload.results, "plan");
		const planOut = plan?.structuredOutput && typeof plan.structuredOutput === "object"
			? (plan.structuredOutput as { decisionsRequiringApproval?: unknown })
			: undefined;
		const decisions = Array.isArray(planOut?.decisionsRequiringApproval)
			? (planOut?.decisionsRequiringApproval as unknown[]).filter((d): d is string => typeof d === "string")
			: [];
		if (decisions.length > 0) {
			markNeedsApproval(decisions, "the plan");
			ctx.ui.notify(`Factory paused for approval:\n${decisions.map((d) => `  - ${d}`).join("\n")}`, "warning");
			return;
		}
		state.phase = "needs_attention";
		state.error = "build workflow finished without a valid implement handoff (missing or malformed structured output).";
		state.updatedAt = nowIso();
		save();
		updateStatus(ctx);
		ctx.ui.notify(`Factory needs attention: ${state.error}`, "warning");
	};

	const handleReviewCompletion = async (ctx: ExtensionContext, payload: Record<string, unknown>, config: FactoryConfig) => {
		if (!state) return;
		state.reviewMissionId = state.reviewMissionId ?? (state.reviewRunId ? await queryMissionId(state.reviewRunId) : undefined);
		if (payload.success === false || payload.stopped === true || payload.timedOut === true || payload.interrupted === true) {
			state.phase = "failed";
			state.error = `review workflow did not complete (state: ${String(payload.state ?? "unknown")}, summary: ${boundedSummary(payload.summary)}).`;
			state.updatedAt = nowIso();
			save();
			updateStatus(ctx);
			ctx.ui.notify(`Factory failed: ${state.error}`, "error");
			return;
		}
		const fix = childStructuredOutput(payload.results, "fix");
		const fixHandoff = fix?.status === "completed" ? handoffFromStructuredOutput(fix.structuredOutput) : undefined;
		if (fixHandoff) {
			const fixOut = fix?.structuredOutput as { decisionsRequiringApproval?: unknown } | undefined;
			const decisions = Array.isArray(fixOut?.decisionsRequiringApproval)
				? (fixOut?.decisionsRequiringApproval as unknown[]).filter((d): d is string => typeof d === "string")
				: [];
			if (decisions.length > 0) {
				markNeedsApproval(decisions, "the fix pass");
				ctx.ui.notify(`Factory paused for approval:\n${decisions.map((d) => `  - ${d}`).join("\n")}`, "warning");
				return;
			}
			state.handoff = fixHandoff;
			state.reviewVerdict = "fix (one fix pass applied)";
			state.outcome = "fixed";
			await runFinalChecksAndFinish(ctx, config);
			return;
		}
		// No fix pass ran: derive the disposition from structured verdicts only.
		const reviewEntries = (Array.isArray(payload.results) ? payload.results : []) as Array<Record<string, unknown>>;
		const verdicts = reviewEntries
			.filter((entry) => typeof entry.workflowKey === "string" && (entry.workflowKey as string).startsWith("review-"))
			.map((entry) => {
				const so = entry.structuredOutput && typeof entry.structuredOutput === "object"
					? (entry.structuredOutput as { verdict?: unknown; findings?: unknown[]; remainingRisks?: unknown[] })
					: undefined;
				const verdict = so && (so.verdict === "ok" || so.verdict === "fix" || so.verdict === "blocked") ? so.verdict : "blocked";
				return {
					key: entry.workflowKey as string,
					verdict,
					findings: Array.isArray(so?.findings) ? so?.findings : [],
				};
			});
		state.reviewVerdict = verdicts.map((v) => `${v.key}=${v.verdict}`).join(", ");
		const blocked = verdicts.filter((v) => v.verdict === "blocked");
		if (blocked.length > 0) {
			const decisions = blocked.flatMap((v) =>
				v.findings
					.filter((f): f is Record<string, unknown> => Boolean(f) && typeof f === "object")
					.map((f) => `${v.key}: ${String(f.summary ?? "unspecified")} (${String(f.file ?? "?")}:${String(f.line ?? "?")})`),
			);
			state.outcome = "blocked";
			markNeedsApproval(decisions, "review");
			ctx.ui.notify(`Factory blocked by review (requires human decisions):\n${decisions.map((d) => `  - ${d}`).join("\n")}`, "warning");
			return;
		}
		state.outcome = "ok";
		await runFinalChecksAndFinish(ctx, config);
	};

	const boundedSummary = (value: unknown): string =>
		typeof value === "string" ? value.slice(0, 300) : "(no summary)";

	// Completion correlation: only exact run ids we launched advance the pipeline.
	pi.events.on(ASYNC_COMPLETE_EVENT, (raw) => {
		const payload = (raw && typeof raw === "object" ? raw : {}) as Record<string, unknown>;
		const runId = typeof payload.runId === "string" ? payload.runId : undefined;
		if (!state || !runId) return;
		const isBuild = state.phase === "build" && runId === state.buildRunId;
		const isReview = state.phase === "review" && runId === state.reviewRunId;
		if (!isBuild && !isReview) return;
		const config = loadConfigForPipeline();
		if (!config) {
			if (state) {
				state.phase = "needs_attention";
				state.error = "factory config disappeared or became invalid mid-run.";
				state.updatedAt = nowIso();
				save();
			}
			return;
		}
		const step = isBuild
			? handleBuildCompletion(activeCtx, payload, config)
			: handleReviewCompletion(activeCtx, payload, config);
		step.catch((error) => {
			if (!state) return;
			state.phase = "failed";
			state.error = `factory continuation crashed: ${error instanceof Error ? error.message : String(error)}`;
			state.updatedAt = nowIso();
			save();
			updateStatus(activeCtx);
		});
	});

	// The context captured at completion time; refreshed on every session_start.
	let activeCtx: ExtensionContext | undefined;
	const loadConfigForPipeline = (): FactoryConfig | undefined => {
		if (!activeCtx || !state) return undefined;
		try {
			const path = join(activeCtx.cwd, CONFIG_DIR_NAME, FACTORY_CONFIG_FILENAME);
			const parsed = parseFactoryConfig(JSON.parse(readFileSync(path, "utf8")));
			return parsed.ok ? parsed.config : undefined;
		} catch {
			return undefined;
		}
	};

	// ---- Lifecycle ------------------------------------------------------

	pi.on("session_start", async (_event, ctx) => {
		activeCtx = ctx;
		restore(ctx);
		updateStatus(ctx);
	});
	pi.on("session_tree", async (_event, ctx) => {
		activeCtx = ctx;
		restore(ctx);
		updateStatus(ctx);
	});

	// ---- Commands -------------------------------------------------------

	pi.registerCommand("factory", {
		description: "Run the bounded software factory: scout → plan → implement → checks → review → optional fix → final checks",
		handler: async (args, ctx) => {
			const task = (args ?? "").trim();
			if (!task) {
				ctx.ui.notify("Usage: /factory <task>", "error");
				return;
			}
			await ctx.waitForIdle();
			if (state && ACTIVE_PHASES.includes(state.phase)) {
				ctx.ui.notify(`A factory run is already active (phase: ${state.phase}). Check /factory-status; stop or finish it first.`, "warning");
				return;
			}
			if (!ctx.isProjectTrusted()) {
				ctx.ui.notify("/factory refuses to run in an untrusted project.", "error");
				return;
			}
			const config = loadConfig(ctx);
			if (!config) return;
			if (!(await validateBaseline(ctx, config))) return;
			try {
				await rpcPing(pi.events);
			} catch (error) {
				ctx.ui.notify(error instanceof Error ? error.message : String(error), "error");
				return;
			}

			let script: string;
			try {
				script = buildBuildWorkflowScript({ task });
			} catch (error) {
				ctx.ui.notify(error instanceof Error ? error.message : String(error), "error");
				return;
			}

			state = {
				task,
				phase: "build",
				startedAt: nowIso(),
				updatedAt: nowIso(),
			};
			try {
				const runId = await spawnWorkflow(script, { task, phase: "build" }, config);
				state.buildRunId = runId;
				state.buildMissionId = await queryMissionId(runId);
			} catch (error) {
				state = {
					task,
					phase: "failed",
					error: `failed to launch build workflow: ${error instanceof Error ? error.message : String(error)}`,
					startedAt: nowIso(),
					updatedAt: nowIso(),
				};
				save();
				ctx.ui.notify(`Factory failed to start: ${state.error}`, "error");
				return;
			}
			save();
			updateStatus(ctx, "factory: building");
			ctx.ui.notify(
				`Factory launched (build run ${state.buildRunId}${state.buildMissionId ? `, mission ${state.buildMissionId}` : ""}). ` +
					`Pipeline: scout → plan → implement → checks → review → fix? → final checks. ` +
					`No commit, push, deploy, or release will be performed.`,
				"info",
			);
		},
	});

	pi.registerCommand("factory-status", {
		description: "Show the latest software factory run (phase, run/mission ids, checks, verdict)",
		handler: async (_args, ctx) => {
			if (!state) {
				ctx.ui.notify("No factory run in this session yet. Start one with /factory <task>.", "info");
				return;
			}
			// Best-effort live state for the currently active workflow.
			const liveRunId = state.phase === "build" ? state.buildRunId : state.phase === "review" ? state.reviewRunId : undefined;
			let liveLine: string | undefined;
			if (liveRunId) {
				try {
					const data = await rpcRequest<{ text?: string }>(pi.events, "status", { id: liveRunId }, { timeoutMs: 20_000 });
					const stateLine = /State:\s+(\S+)/.exec(data?.text ?? "")?.[1];
					if (stateLine) liveLine = `  Live workflow state: ${stateLine}`;
				} catch (error) {
					liveLine = `  Live workflow state: unavailable (${error instanceof FactoryRpcError ? error.code : "error"})`;
				}
			}
			ctx.ui.notify(formatState(state) + (liveLine ? `\n${liveLine}` : ""), "info");
		},
	});

	void randomUUID; // keep import tree-shake-proof for future request ids
}

